solutionCode:
function createDeferredValue(initialValue, delayMs = 15) {
  let deferred = initialValue;
  let timerId = null;

  function update(newVal) {
    if (timerId !== null) clearTimeout(timerId);
    timerId = setTimeout(() => {
      deferred = newVal;
      timerId = null;
    }, delayMs);
  }

  function get() {
    return deferred;
  }

  return { update, get };
}
